                    "customer_id": customer.customer_id,
                    "name": customer.name,
                    "lifetime_value_cents": lifetime_value_cents,
                })

        customer_values.sort(key=lambda x: (-x["lifetime_value_cents"], x["customer_id"]))

        return Response(200, {
            "customers": customer_values[:limit],
        })

    def handle_customers_without_orders(self) -> Response:
        customers = self._customers.list_all()
        result = []

        for customer in customers:
            orders = self._order_service.list_for_customer(customer.customer_id)
            has_non_cancelled = any(order.status != "cancelled" for order in orders)

            if not has_non_cancelled:
                result.append({
                    "customer_id": customer.customer_id,
                    "name": customer.name,
                    "email": customer.email,
                })

        return Response(200, {
            "customers": result,
        })
